def unpack(b, kind):
    if kind == 'axis_leak':
        return np.c_[b, b, np.zeros((2, 4))]
    if kind == 'leak':
        return np.c_[b.reshape(2, 2), np.zeros((2, 4))]
    if kind == 'leak_diff':
        return np.c_[b.reshape(2, 4), np.zeros((2, 2))]
    return b.reshape(2, 6)
